import csv
from collections import defaultdict
from datetime import datetime

def analyze_attendance(csv_file_path):
    # Define a threshold for what constitutes a "late arrival"
    # Assuming 9:00 AM as the expected arrival time
    late_threshold = datetime.strptime('09:00:00', '%H:%M:%S').time()

    # Dictionary to store late arrival counts per employee
    late_arrivals = defaultdict(int)

    try:
        with open(csv_file_path, 'r') as file:
            reader = csv.DictReader(file)

            for row in reader:
                try:
                    employee_name = row['Name']
                    check_in_time_str = row['Check-in Time']

                    # Parse the check-in time
                    check_in_time = datetime.strptime(check_in_time_str, '%H:%M:%S').time()

                    # Check if the employee arrived late
                    if check_in_time > late_threshold:
                        late_arrivals[employee_name] += 1

                except KeyError as e:
                    print(f"Missing column in CSV: {e}")
                    continue
                except ValueError as e:
                    print(f"Error parsing time data for {row.get('Name', 'Unknown')}: {e}")
                    continue

    except FileNotFoundError:
        print(f"File not found: {csv_file_path}")
        return []
    except Exception as e:
        print(f"Error reading file: {e}")
        return []

    # Sort employees by late arrival count (descending) and get top 5
    top_latecomers = sorted(late_arrivals.items(), key=lambda x: x[1], reverse=True)[:5]

    return top_latecomers

def append_to_problematic_employees(top_latecomers, output_file):
    try:
        with open(output_file, 'a') as file:
            file.write("\n# Top Late Arrivals:\n")
            for name, count in top_latecomers:
                file.write(f"{name} ({count} late arrivals)\n")
        print(f"Appended top latecomers to {output_file}")
    except Exception as e:
        print(f"Error writing to file: {e}")

if __name__ == "__main__":
    import sys

    if len(sys.argv) != 2:
        print("Usage: python attendance_analyzer.py <csv_file>")
        sys.exit(1)

    csv_file = sys.argv[1]
    output_file = "/tmp/mcp-workspace/problematic_employees.txt"

    # Create or initialize the output file if it doesn't exist
    try:
        with open(output_file, 'x') as f:
            f.write("# Problematic Employees\n")
    except FileExistsError:
        pass  # File already exists

    top_latecomers = analyze_attendance(csv_file)

    if top_latecomers:
        print("Top 5 Late Arrivals:")
        for i, (name, count) in enumerate(top_latecomers, 1):
            print(f"{i}. {name}: {count} late arrivals")

        append_to_problematic_employees(top_latecomers, output_file)
    else:
        print("No late arrival data found.")
